<?php
/**
 * Script del quiz: è quello del prototipo (stessi punteggi, stesse esportazioni), con tre differenze:
 * dati e chiave del salvataggio arrivano da CONF; le scelte sono un gruppo di radio accessibile (frecce, tasti 1–5,
 * il focus resta sulla scelta fatta); il focus passa alla domanda quando cambia.
 */
defined( 'ABSPATH' ) || exit;

function scb_js_quiz() {
	return <<<'JS'
'use strict';
const QUESTIONS = CONF.questions;
const META = CONF.meta;
const DRIVER_KEYS=['dp','ds','dt','dh','do'], EGO_KEYS=['pn','pa','ad','bl','ba'], FACET_KEYS=['br'];
const STORAGE=CONF.storage;
let state={name:'',index:0,answers:{},date:null};
const $=id=>document.getElementById(id)||document.createElement('div'); // le parti che una pagina non ha (team, esito) diventano elementi vuoti
const names=['Per niente','Poco','Abbastanza','Molto','Moltissimo'];
function load(){try{const d=JSON.parse(localStorage.getItem(STORAGE));if(d&&d.answers&&typeof d.index==='number'){state=d;return true}}catch(e){}return false}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true}catch(e){return false}}
function show(id){for(const name of ['intro','quiz','esito','report']) $(name).classList.toggle('hidden',name!==id);window.scrollTo(0,0)}
function choose(n){const q=QUESTIONS[state.index];state.answers[q.id]=n;persist();display('option')}
function display(focus){show('quiz');const q=QUESTIONS[state.index];$('phase').textContent=q.section==='driver'?'Parte 1 di 2 · Le spinte interiori':'Parte 2 di 2 · Gli stati dell’Io';$('count').textContent=(state.index+1)+' di '+QUESTIONS.length;$('bar').style.width=(((state.index+1)/QUESTIONS.length)*100)+'%';$('question').textContent=q.text;let container=$('options');container.replaceChildren();const current=state.answers[q.id];for(let n=1;n<=5;n++){const b=document.createElement('button');b.type='button';b.className='opt';b.setAttribute('role','radio');b.setAttribute('aria-checked',current===n?'true':'false');b.tabIndex=(current?current===n:n===1)?0:-1;b.dataset.value=String(n);const t=document.createElement('span');t.textContent=names[n-1];const num=document.createElement('span');num.className='num';num.setAttribute('aria-hidden','true');num.textContent=n;b.append(t,num);b.onclick=()=>choose(n);container.append(b)}$('prev').disabled=state.index===0;$('next').disabled=!state.answers[q.id];$('next').textContent=state.index===QUESTIONS.length-1?'Vedi il mio profilo →':'Avanti →';if(focus==='option'){const sel=container.querySelector('[aria-checked="true"]');if(sel)sel.focus()}else if(focus==='question'){$('question').focus({preventScroll:true})}}
function scores(){const out={};Object.keys(META).forEach(key=>{const group=QUESTIONS.filter(q=>q.key===key);const vals=group.map(q=>state.answers[q.id]).filter(x=>typeof x==='number');if(vals.length!==group.length){out[key]=null;return}let sum=0;for(const q of group){let val=state.answers[q.id];sum+=q.reverse?6-val:val}out[key]=Math.round(((sum/group.length)-1)*25)});return out}
function sortKeys(keys,s){return [...keys].sort((a,b)=>(s[b]??-1)-(s[a]??-1))}
function h(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!=null)el.textContent=text;return el}
function appendScore(parent,key,s){const wrap=h('div');const bar=h('div','bar-line');bar.append(h('span','',META[key].label),h('strong','',String(s[key])+' / 100'));const track=h('div','bar-track');track.setAttribute('role','img');track.setAttribute('aria-label',META[key].label+': '+s[key]+' su 100');const fill=h('div','bar-fill');fill.style.width=s[key]+'%';fill.style.background=META[key].color;track.append(fill);wrap.append(bar,track);parent.append(wrap)}
function insight(key,type){const item=h('div','insight');item.append(h('div','tag',type),h('h3','',META[key].label),h('p','',META[key].strength),h('p','',META[key].watch));return item}
function renderReport(){const s=scores();if(Object.values(s).some(x=>x==null)){display('question');return};if(CONF.imp&&!state.lead){mostraEsito(s);return};state.date=state.date||new Date().toISOString();persist();show('report');$('reportTitle').textContent=state.name?'La bussola di '+state.name:'La tua bussola';$('reportDate').textContent='Compilato il '+new Date(state.date).toLocaleDateString('it-IT');const ds=$('driverScores'),es=$('egoScores'),ins=$('insights');ds.replaceChildren();es.replaceChildren();ins.replaceChildren();sortKeys(DRIVER_KEYS,s).forEach(k=>appendScore(ds,k,s));sortKeys(EGO_KEYS,s).forEach(k=>appendScore(es,k,s));const sub=h('div','divider');es.append(sub,h('div','tag','Ulteriore modalità esplorativa'));appendScore(es,'br',s);const sortedDrivers=sortKeys(DRIVER_KEYS,s),sortedEgo=sortKeys(EGO_KEYS,s);ins.append(insight(sortedDrivers[0],'Spinta più riconosciuta'),insight(sortedDrivers[1],'Seconda spinta'),insight(sortedEgo[0],'Stato dell’Io più riconosciuto'),insight(sortedEgo[1],'Secondo stato dell’Io'));$('experiment').replaceChildren(h('strong','',META[sortedDrivers[0]].label+': un piccolo cambiamento'),h('p','',META[sortedDrivers[0]].practice));aggiornaAi(s);if(CONF.imp)tipoImp(s);$('reportTitle').focus({preventScroll:true})}
function fileDownload(filename, content, mime='application/json'){const blob=new Blob([content],{type:mime+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function uuid(){return (typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function')?crypto.randomUUID():'anon-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
function exportAnon(){const s=scores();state.anon_id=state.anon_id||uuid();persist();const data={schema:'bussola-team-anon-v1',version:'1.0',response_id:state.anon_id,completed_at:state.date,scores:s,scale_info:'Indicativi, non validati',raw_responses_included:false};fileDownload('bussola-team-anonimo.json',JSON.stringify(data,null,2))}
function exportPersonal(){const data={schema:'bussola-team-personal-v1',name:state.name||null,completed_at:state.date,answers:state.answers,scores:scores(),questions_version:'1.0'};fileDownload('bussola-personale.json',JSON.stringify(data,null,2))}
function clearData(){if(!confirm('Eliminare tutte le tue risposte da questo browser? Le esportazioni già scaricate resteranno nei tuoi file.'))return;try{localStorage.removeItem(STORAGE)}catch(e){}state={name:'',index:0,answers:{},date:null};$('personname').value='';$('agree').checked=false;$('start').disabled=true;$('resume').classList.add('hidden');['promptMio','schedaMia','schedeColleghi','promptTeam','nomeTeam'].forEach(id=>$(id).value='');$('bloccoTeam').classList.add('hidden');$('riconosciute').textContent='Nessuna scheda incollata.';show('intro')}
$('agree').onchange=e=>$('start').disabled=!e.target.checked;$('start').onclick=()=>{state={name:$('personname').value.trim(),index:0,answers:{},date:null,t0:Date.now()};persist();display('question')};$('resume').onclick=()=>{const missing=QUESTIONS.findIndex(q=>!state.answers[q.id]);if(missing===-1)renderReport();else {state.index=Math.min(state.index,missing);display('question')}};$('prev').onclick=()=>{state.index=Math.max(0,state.index-1);persist();display('question')};$('next').onclick=()=>{if(!state.answers[QUESTIONS[state.index].id])return;if(state.index===QUESTIONS.length-1){renderReport()}else{state.index++;persist();display('question')}};$('saveprogress').onclick=()=>{alert(persist()?'Avanzamento salvato in questo browser.':'Salvataggio locale non disponibile: lascia aperta la pagina oppure completa ed esporta.')};$('reset').onclick=clearData;$('delete').onclick=clearData;$('anon').onclick=exportAnon;$('personal').onclick=exportPersonal;$('print').onclick=()=>window.print();$('copy').onclick=()=>{const s=scores(),line=sortKeys(DRIVER_KEYS,s).map(k=>META[k].label+': '+s[k]).join(', '),e=sortKeys(EGO_KEYS,s).map(k=>META[k].label+': '+s[k]).join(', '),txt='La Bussola Interna — sintesi personale (non validata)\nDriver: '+line+'\nStati dell’Io: '+e+'\nModalità esplorativa Bambino Ribelle: '+s.br;const success=()=>alert('Sintesi copiata.');if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt).then(success).catch(()=>prompt('Copia la sintesi:',txt));else prompt('Copia la sintesi:',txt)};
// Tastiera: frecce dentro il gruppo di scelte (come i radio), tasti 1–5 su tutta la domanda.
$('options').addEventListener('keydown',e=>{const keys={ArrowDown:1,ArrowRight:1,ArrowUp:-1,ArrowLeft:-1};if(!(e.key in keys))return;e.preventDefault();const cur=Number(document.activeElement&&document.activeElement.dataset.value)||1;let n=cur+keys[e.key];if(n<1)n=5;if(n>5)n=1;choose(n)});
document.addEventListener('keydown',e=>{if($('quiz').classList.contains('hidden')||e.altKey||e.ctrlKey||e.metaKey)return;const t=e.target;if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'))return;if(/^[1-5]$/.test(e.key)){e.preventDefault();choose(Number(e.key))}});
// ─── Lettura con l'AI e scambio delle schede tra colleghi (tutto nel browser; parte solo al tocco) ───
const CONTESTO='«La Bussola Interna» è un questionario esplorativo NON validato, ispirato all’Analisi Transazionale: le cinque spinte interiori (driver: Sii perfetto, Sii forte, Sforzati, Sbrigati, Compiaci gli altri) e gli stati dell’Io. Ogni punteggio va da 0 a 100 ed è (media delle risposte da 1 a 5 − 1) × 25: più alto vuol dire solo più accordo con le affermazioni di quella dimensione, non è un percentile né una misura clinica. «Bambino Ribelle» è una dimensione esplorativa.';
const REGOLE='Regole: non fare diagnosi e non dare etichette di personalità; usa «può», «tende a», mai «sei»; non giudicare capacità o prestazioni e non suggerire di usare questi dati per valutare le persone; non dedurre più di quanto dicono i numeri; se ti serve contesto sul nostro lavoro, fai prima una o due domande. Rispondi in italiano, con un tono caldo e concreto.';
const AI={chatgpt:{url:'https://chatgpt.com/',q:true,nome:'ChatGPT'},gemini:{url:'https://gemini.google.com/app',q:false,nome:'Gemini'}};
function righe(s){return {driver:sortKeys(DRIVER_KEYS,s).map(k=>META[k].label+' '+s[k]).join(' · '),ego:sortKeys(EGO_KEYS,s).map(k=>META[k].label+' '+s[k]).join(' · '),br:s.br}}
function promptPersonale(s){const r=righe(s);if(CONF.imp)return promptImp(s,r);return ['Ciao! Vorrei il tuo aiuto, come facilitatore esperto di comunicazione nei team di lavoro, per leggere i miei risultati della «Bussola Interna».','',CONTESTO,'','I miei punteggi:','- Spinte interiori: '+r.driver,'- Stati dell’Io: '+r.ego,'- Bambino Ribelle (esplorativo): '+r.br,'','Cosa ti chiedo:','1. Una lettura breve di come posso tendere a comunicare e collaborare, soprattutto sotto pressione: punti di forza e possibili trappole.','2. Come preferisco probabilmente ricevere richieste, feedback, urgenze e disaccordi, e tre consigli concreti per i colleghi che lavorano con me.','3. Tre consigli concreti per me, per comunicare meglio con chi ha spinte diverse dalle mie.','4. Due piccoli esperimenti da provare la prossima settimana.','5. Una «carta della collaborazione» di 5 righe, in prima persona, da condividere con il team.','',REGOLE].join('\n')}
function pulisciNome(n){return String(n||'').replace(/[\[\]|\r\n]/g,' ').replace(/\s+/g,' ').trim().slice(0,40)}
function codice(nome,s){return '[BT1|'+nome+'|'+Object.keys(META).map(k=>k+'='+s[k]).join(';')+']'}
function scheda(nome,s){const r=righe(s);return ['La Bussola Interna · scheda di '+nome,'Spinte interiori: '+r.driver,'Stati dell’Io: '+r.ego,'Bambino Ribelle (esplorativo): '+r.br,'Strumento esplorativo e non validato: serve a capire come collaborare, non a giudicare. Incollala nella tua Bussola, sezione «Confrontati con il team».',codice(nome,s)].join('\n')}
function leggiSchede(txt){const out=[];const re=/\[BT1\|([^|\]\r\n]{0,40})\|([a-z]{2}=\d{1,3}(?:;[a-z]{2}=\d{1,3})*)\]/g;let m;while((m=re.exec(txt))){const sc={};m[2].split(';').forEach(p=>{const [k,v]=p.split('=');sc[k]=Number(v)});if(!Object.keys(META).every(k=>Number.isInteger(sc[k])&&sc[k]>=0&&sc[k]<=100))continue;const nome=pulisciNome(m[1])||'Collega';if(!out.some(o=>o.nome===nome&&codice(nome,o.s)===codice(nome,sc)))out.push({nome,s:sc})}return out}
function promptTeam(io,colleghi){const persone=[io,...colleghi];const blocchi=persone.map((p,i)=>{const r=righe(p.s);return '■ '+p.nome+(i===0?' (sono io)':'')+'\n- Spinte interiori: '+r.driver+'\n- Stati dell’Io: '+r.ego+'\n- Bambino Ribelle: '+r.br});return ['Ciao! Lavoriamo nello stesso team e abbiamo compilato «La Bussola Interna». Vorremmo il tuo aiuto, come facilitatore esperto di comunicazione nei team, per capire come collaborare e comunicare meglio tra noi.','',CONTESTO,'','I punteggi di '+persone.length+' persone (ognuna ha scelto di condividerli):','',blocchi.join('\n\n'),'','Cosa ti chiediamo:','1. Una mappa del team: dove ci somigliamo e dove ci completiamo.','2. Per ogni persona: come preferisce probabilmente ricevere richieste, feedback e urgenze, e cosa la aiuta quando è sotto pressione.','3. Le coppie che potrebbero fraintendersi più spesso: dove può nascere l’attrito e una frase concreta che può aiutare.','4. Cinque accordi di comunicazione per tutto il team (riunioni, scadenze, feedback, richieste di aiuto, disaccordi).','5. Un esercizio di 20 minuti da fare insieme per parlarne.','',REGOLE+' Non fare classifiche tra le persone e non dire chi è «migliore» o «peggiore».'].join('\n')}
function nomeTeam(){return pulisciNome($('nomeTeam').value)||'Collega'}
function aggiornaTeam(){if(!document.getElementById('team'))return;const s=scores();if(Object.values(s).some(x=>x==null))return;$('schedaMia').value=scheda(nomeTeam(),s);const colleghi=leggiSchede($('schedeColleghi').value).filter(c=>codice(c.nome,c.s)!==codice(nomeTeam(),s));const n=colleghi.length;$('riconosciute').textContent=$('schedeColleghi').value.trim()?(n?'Schede riconosciute: '+n+' ('+colleghi.map(c=>c.nome).join(', ')+').':'Nessuna scheda riconosciuta: incolla il testo completo, con la riga che inizia con [BT1|.'):'Nessuna scheda incollata.';$('bloccoTeam').classList.toggle('hidden',!n);if(n)$('promptTeam').value=promptTeam({nome:nomeTeam(),s},colleghi)}
function aggiornaAi(s){$('promptMio').value=promptPersonale(s);if(!$('nomeTeam').value)$('nomeTeam').value=pulisciNome(state.nome_team||state.name);aggiornaTeam()}
function copia(txt){return (navigator.clipboard&&navigator.clipboard.writeText)?navigator.clipboard.writeText(txt).then(()=>true,()=>false):Promise.resolve(false)}
function avvisa(id,txt){$(id).textContent='';setTimeout(()=>{$(id).textContent=txt},50)}
document.querySelectorAll('[data-ai]').forEach(b=>b.addEventListener('click',()=>{const txt=$(b.dataset.fonte).value.trim();if(!txt)return;const dove=b.dataset.ai,av=b.dataset.fonte==='promptTeam'?'avvisoTeam':'avvisoAi';if(dove==='copia'){copia(txt).then(ok=>ok?avvisa(av,'Prompt copiato.'):prompt('Copia il prompt:',txt));return}const a=AI[dove],q=encodeURIComponent(txt),conQ=a.q&&q.length<=7000;window.open(a.url+(conQ?'?q='+q:''),'_blank','noopener');copia(txt).then(ok=>avvisa(av,conQ?'Si è aperto '+a.nome+' con il prompt già scritto: controllalo e invialo.':(ok?'Prompt copiato: in '+a.nome+' tocca il campo del messaggio, scegli «Incolla» e invia.':'Copia il prompt dal riquadro e incollalo in '+a.nome+'.')))}));
$('nomeTeam').addEventListener('input',()=>{state.nome_team=pulisciNome($('nomeTeam').value);persist();aggiornaTeam()});
$('schedeColleghi').addEventListener('input',aggiornaTeam);
$('copiaScheda').onclick=()=>{const t=$('schedaMia').value;copia(t).then(ok=>ok?alert('Scheda copiata: incollala nel messaggio per i colleghi.'):prompt('Copia la scheda:',t))};
$('condividiScheda').onclick=()=>{const t=$('schedaMia').value;if(navigator.share){navigator.share({title:'La mia Bussola Interna',text:t}).catch(()=>{})}else $('copiaScheda').click()};
// ─── Modalità «Che tipo di imprenditore sei?»: anteprima, modulo, tipo e guida (solo se CONF.imp) ───
function tipoDi(s){return sortKeys(DRIVER_KEYS,s)[0]}
function promptImp(s,r){const t=CONF.types[tipoDi(s)];return ['Ciao! Sono un imprenditore e vorrei il tuo aiuto, come consulente esperto di imprese e comunicazione, per leggere i miei risultati della «Bussola Interna».','',CONTESTO,'','Il mio profilo prevalente: «'+t.nome+'» (spinta '+META[tipoDi(s)].label+').','I miei punteggi:','- Spinte interiori: '+r.driver,'- Stati dell’Io: '+r.ego,'- Bambino Ribelle (esplorativo): '+r.br,'','Cosa ti chiedo:','1. Una lettura breve di come tendo a guidare la mia impresa e a decidere, soprattutto sotto pressione: punti di forza e possibili trappole.','2. Come posso comunicare meglio con clienti, collaboratori e soci, e come preferisco probabilmente ricevere richieste, feedback e urgenze.','3. Cosa significa per il marketing e i social della mia impresa: tre consigli concreti, adatti a poco tempo e budget limitato.','4. Due piccoli esperimenti da provare la prossima settimana.','5. Le domande che mi faresti per conoscere meglio la mia impresa e darmi consigli più precisi.','',REGOLE].join('\n')}
function mostraEsito(s){const t=CONF.types[tipoDi(s)];show('esito');$('tipo-anteprima').textContent=t.nome;$('motto-anteprima').textContent='«'+t.motto+'» Il profilo completo è qui sotto, appena compili il modulo.';$('tipo-anteprima').focus({preventScroll:true})}
function tipoImp(s){const t=CONF.types[tipoDi(s)];$('tipo-nome').textContent=t.nome;$('tipo-motto').textContent='«'+t.motto+'»';$('tipo-ritratto').textContent=t.ritratto+' La seconda spinta che ti muove è «'+META[sortKeys(DRIVER_KEYS,s)[1]].label+'».';$('tipo-forza').textContent=t.forza;$('tipo-social').textContent=t.social;if(state.guida){$('scarica-guida').href=state.guida;$('nome-settore').textContent=state.settore||'';$('box-guida').classList.remove('hidden')}else $('box-guida').classList.add('hidden')}
function erroreCampo(el,msg){el.setAttribute('aria-invalid','true');$('errore-form').textContent=msg;el.focus();return false}
function controllaModulo(f){f.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));const v=id=>$(id).value.trim();if(!v('f-nome'))return erroreCampo($('f-nome'),'Scrivi il tuo nome.');if(!v('f-cognome'))return erroreCampo($('f-cognome'),'Scrivi il tuo cognome.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v('f-email')))return erroreCampo($('f-email'),'Controlla l’indirizzo email.');if(v('f-telefono').replace(/[^\d]/g,'').length<8)return erroreCampo($('f-telefono'),'Scrivi un numero di telefono completo.');if(!v('f-provincia'))return erroreCampo($('f-provincia'),'Scegli la provincia.');if(!v('f-azienda'))return erroreCampo($('f-azienda'),'Scrivi il nome della tua azienda.');if(!v('f-settore'))return erroreCampo($('f-settore'),'Scegli il settore.');if(!$('f-privacy').checked)return erroreCampo($('f-privacy'),'Per ricevere il profilo e la guida serve la presa visione dell’informativa privacy.');return true}
function utm(){try{const p=new URLSearchParams(location.search);return ['utm_source','utm_medium','utm_campaign'].map(k=>p.get(k)).filter(Boolean).join(' / ').slice(0,200)}catch(e){return ''}}
$('modulo').addEventListener('submit',async e=>{e.preventDefault();const f=e.target;$('errore-form').textContent='';if(!controllaModulo(f))return;const s=scores();const btn=$('invia');btn.disabled=true;btn.textContent='Un momento…';const dati={nome:$('f-nome').value.trim(),cognome:$('f-cognome').value.trim(),email:$('f-email').value.trim(),telefono:$('f-telefono').value.trim(),provincia:$('f-provincia').value,azienda:$('f-azienda').value.trim(),settore:$('f-settore').value,privacy:$('f-privacy').checked,marketing:$('f-marketing').checked,sito_web:$('f-sito').value,punteggi:s,ms:Date.now()-(state.t0||Date.now()),utm:utm()};try{const r=await fetch(CONF.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(dati),credentials:'same-origin'});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){$('errore-form').textContent=(j&&j.errore)||'Qualcosa non ha funzionato: riprova tra poco.';btn.disabled=false;btn.textContent='Mostrami il profilo completo →';return}state.lead=true;state.name=dati.nome;state.guida=j.guida;state.settore=j.settore;persist();renderReport()}catch(err){$('errore-form').textContent='Connessione assente: controlla la rete e riprova.';btn.disabled=false;btn.textContent='Mostrami il profilo completo →'}});
if(load()){$('personname').value=state.name||'';$('resume').classList.remove('hidden')}
JS;
}
